window.BANK.chemistry = {"name":"Chemistry","sets":[{"name":"Set 1: Separation, Laws, Mole and Gases","qs":[["The best method to obtain salt from sea water is:",["filtration","evaporation","decantation","magnetization"],1,"Evaporating water leaves the dissolved salt behind."],["Which mixture can be separated using a magnet?",["sand and water","iron filings and sulphur","salt and water","ink and water"],1,"Iron is magnetic, sulphur is not."],["Oil and water are best separated by:",["distillation","decantation","sublimation","crystallization"],1,"Immiscible liquids separate in layers and can be poured off."],["A compound always contains the same elements in the same proportion by mass. This is the law of:",["multiple proportions","definite proportions","Avogadro","Boyle"],1,"Law of definite proportions (Proust)."],["Avogadro's number is:",["6.02 ×10²³","3.01 ×10²³","6.02 ×10²¹","1.0 ×10²³"],0,"One mole contains 6.02 ×10²³ particles."],["The molar volume of a gas at STP is:",["11.2 dm3","22.4 dm3","44.8 dm3","2.24 dm3"],1,"One mole of any gas occupies 22.4 dm3 at STP."],["Relative molecular mass of water (H = 1, O = 16) is:",["16","17","18","20"],2,"2(1) + 16 = 18."],["1 dm3 of hydrogen reacts with 1 dm3 of chlorine. Volume of HCl formed is:",["1 dm3","2 dm3","0.5 dm3","3 dm3"],1,"Gay-Lussac: 1 vol H2 + 1 vol Cl2 gives 2 vol HCl."],["At constant temperature, if the pressure of a gas doubles, its volume becomes:",["doubled","halved","the same","quadrupled"],1,"Boyle's law: PV is constant, so V halves."],["2 dm3 of gas at 273 K is heated to 546 K at constant pressure. New volume is:",["1 dm3","2 dm3","4 dm3","8 dm3"],2,"V1/T1 = V2/T² gives V2 = 4 dm3."],["The value of the gas constant R in SI units is:",["8.31 J/mol K","6.02","22.4","9.81"],0,"R = 8.31 J mol-1 K-1."],["Brownian motion is evidence that:",["particles are in random motion","gases have no mass","liquids are compressible","solids flow"],0,"Visible particles jiggle because of collisions with fast-moving molecules."],["Melting is the change of state from:",["solid to liquid","liquid to gas","gas to liquid","solid to gas"],0,"Melting turns a solid into a liquid."],["Which gas diffuses faster, hydrogen or oxygen? (Graham's law)",["oxygen","hydrogen","same rate","neither"],1,"Rate is inversely proportional to √ of molar mass; H2 is lighter."],["A gas has relative molecular mass 44. Its vapour density is:",["11","22","44","88"],1,"Vapour density = M/2 = 22."]]},{"name":"Set 2: Atomic Structure, Bonding, Nuclear, Air and Water","qs":[["Sodium has atomic number 11 and mass number 23. Number of neutrons is:",["11","12","23","34"],1,"Neutrons = mass number - atomic number = 23 - 11 = 12."],["Isotopes of an element differ in their:",["atomic number","number of neutrons","number of protons","electron arrangement"],1,"Same protons, different neutrons, so different mass number."],["Electron arrangement of magnesium (Z = 12) is:",["2,8,2","2,8,1","2,8,3","2,2,8"],0,"Mg has 12 electrons: 2, 8, 2."],["The electron was discovered by:",["Rutherford","Thomson","Bohr","Dalton"],1,"J.J. Thomson discovered the electron using cathode rays."],["Rutherford's gold foil experiment showed that the atom has:",["electrons in shells","a small dense positive nucleus","solid sphere structure","neutrons in the nucleus"],1,"Most particles passed through, a few deflected by a dense nucleus."],["Group 17 elements are called:",["alkali metals","halogens","noble gases","transition metals"],1,"Halogens: F, Cl, Br, I."],["The element with a noble gas (stable) configuration is:",["sodium","chlorine","neon","magnesium"],2,"Neon has a full outer shell of 8 electrons."],["The bond in sodium chloride is:",["covalent","ionic (electrovalent)","metallic","hydrogen"],1,"Na transfers an electron to Cl, forming ions."],["The shape of methane (CH4) is:",["linear","tetrahedral","pyramidal","planar"],1,"CH4 is tetrahedral with bond angles of about 109.5 degrees."],["The shape of ammonia (NH3) is:",["tetrahedral","pyramidal","linear","planar"],1,"NH3 has a lone pair, so it is pyramidal."],["The shape of water (H2O) is:",["linear","non-linear (bent)","tetrahedral","pyramidal"],1,"Water is bent because of two lone pairs."],["An alpha particle is:",["an electron","a helium nucleus","a proton","a photon"],1,"Alpha particle = 2 protons + 2 neutrons."],["A 40 g sample of a radioactive material has a half-life of 1 year. Mass left after 2 years is:",["20 g","10 g","5 g","40 g"],1,"40 to 20 to 10 g after two half-lives."],["Which statement is correct?",["a nuclear reaction changes the nucleus; a chemical reaction changes electrons","both change the nucleus","chemical reactions change the nucleus","neither changes anything"],0,"Nuclear reactions involve the nucleus; chemical reactions involve outer electrons."],["Temporary hardness of water is removed by:",["boiling","adding salt","filtering","decanting"],0,"Boiling precipitates the hardness-causing carbonates."]]},{"name":"Set 3: Matter, Separation and States","qs":[["Which property is a chemical property of a substance?",["density","melting point","reactivity with acid","colour"],2,"Chemical properties describe how a substance reacts to form new substances."],["Filtration is used to separate:",["salt from water","sand from water","alcohol from water","oil from water"],1,"Filtration separates an insoluble solid from a liquid."],["Fractional distillation separates crude oil because its components have different:",["colours","boiling points","densities only","masses"],1,"Each fraction condenses at a different temperature."],["Sublimation is the change of state from:",["solid to liquid","liquid to gas","solid to gas","gas to liquid"],2,"Solids like iodine and ammonium chloride pass straight to gas."],["The process of separating a mixture of two miscible liquids with different boiling points is:",["filtration","decantation","fractional distillation","sublimation"],2,"Miscible liquids are separated by their boiling points."],["Which of these is a pure substance?",["air","sea water","distilled water","bronze"],2,"Distilled water has only one kind of molecule, H2O."],["Chromatography is used mainly to:",["separate coloured components of a mixture","make alloys","measure pH","purify metals"],0,"Components travel at different rates on the paper or medium."],["A heterogeneous mixture has:",["uniform composition throughout","two or more visibly distinct phases","one phase only","fixed melting point"],1,"Heterogeneous mixtures show different parts when looked at closely."],["The particles of a solid are:",["far apart and moving freely","close, fixed and vibrating","close and sliding freely","absent"],1,"Solids have fixed shape and volume due to strong forces."],["Which process absorbs heat energy?",["condensation","freezing","melting","deposition"],2,"Melting needs energy to overcome forces between particles."],["Brass is best described as:",["an element","a compound","an alloy","a mixture of gases"],2,"Brass is a mixture of copper and zinc, an alloy."],["Magnetism is used to separate iron from sulphur because:",["iron is non-metal","iron is attracted to a magnet","sulphur is magnetic","both dissolve in water"],1,"Iron is ferromagnetic while sulphur is not."],["The boiling point of pure water at sea level is:",["90 C","100 C","110 C","212 K"],1,"Water boils at 100 C at standard pressure."],["Decantation separates:",["two immiscible liquids or a liquid from a settled solid","two gases","solid solutes from solvents by heat","metals from ores by magnets"],0,"The clear liquid is poured off after settling."],["Evaporation is a process that occurs:",["only at the boiling point","at any temperature from the surface","only in solids","only under pressure"],1,"Surface particles escape at any temperature."]]},{"name":"Set 4: Atoms, Symbols and Isotopes","qs":[["The atomic number of an element is the number of:",["neutrons","protons","nucleons","electrons in shell 3"],1,"Atomic number equals the number of protons."],["The mass number of an atom is the sum of its:",["protons and electrons","protons and neutrons","neutrons and electrons","electrons only"],1,"Nucleons are protons and neutrons."],["Isotopes of an element differ in their number of:",["protons","electrons","neutrons","atomic number"],2,"Isotopes have same protons but different neutrons."],["The symbol for potassium is:",["Po","P","K","Pt"],2,"K comes from Latin kalium."],["An atom has 11 protons and 12 neutrons. Its mass number is:",["11","12","23","22"],2,"Mass number = 11 + 12 = 23."],["The electronic configuration of sodium (Z = 11) is:",["2,8,1","2,9","2,8,2","1,8,2"],0,"Sodium has 11 electrons arranged 2,8,1."],["An ion formed by losing electrons is a:",["anion","cation","isotope","radical"],1,"Losing electrons makes a positive cation."],["Which subatomic particle has the smallest mass?",["proton","neutron","electron","nucleus"],2,"Electrons are much lighter than protons and neutrons."],["Carbon-12 and carbon-14 are:",["allotropes","isotopes","isobars","isomers"],1,"Same atomic number, different mass numbers."],["Isobars are atoms with the same:",["atomic number","mass number","neutron number","electron number only"],1,"Isobars have equal mass numbers but different atomic numbers."],["The maximum number of electrons in the second shell is:",["2","8","18","32"],1,"The second shell holds 2n squared, which is 8."],["The valency of an element with electronic configuration 2,8,6 is:",["2","4","6","8"],0,"Oxygen group elements have valency 2 by gaining two electrons."],["Which is an allotrope of carbon?",["diamond","calcium","carbonate","methane"],0,"Diamond and graphite are allotropes of carbon."],["Rutherford's gold foil experiment showed that the atom:",["is solid","has a small dense nucleus","has electrons in water","has no charge"],1,"Most alpha particles passed through, a few deflected by a dense nucleus."],["Number of neutrons in an atom of chlorine-35 (Z = 17) is:",["17","18","35","52"],1,"35 minus 17 gives 18 neutrons."]]},{"name":"Set 5: Chemical Bonding","qs":[["An ionic bond is formed by:",["sharing electrons","transfer of electrons","sharing protons","transfer of neutrons"],1,"Metals lose electrons to non-metals to form ions."],["Covalent bonds are formed when atoms:",["lose electrons","gain electrons","share electrons","share neutrons"],2,"Atoms share pairs of electrons."],["The compound with the highest melting point is typically:",["covalent molecular","ionic","gas","liquid"],1,"Ionic lattices have strong electrostatic forces."],["The bond between hydrogen and oxygen in water is:",["ionic","covalent","metallic","hydrogen only"],1,"O and H share electrons covalently."],["Metallic bonding involves:",["sharing electrons between two atoms","a sea of delocalised electrons","transfer from metal to metal","nuclear forces"],1,"Delocalised electrons hold metal ions together."],["Which molecule has a triple covalent bond?",["O2","N2","H2O","CO2"],1,"Nitrogen molecule has three shared pairs."],["Electronegativity generally increases across a period from left to right because:",["nuclear charge increases","atomic radius increases","shielding increases","electrons are removed"],0,"More protons pull shared electrons more strongly."],["Hydrogen bonding occurs strongly in:",["CH4","HF","CO2","N2"],1,"H bonded to F, O or N gives strong hydrogen bonds."],["The polar molecule among these is:",["CO2","CCl4","H2O","CH4"],2,"Water has a bent shape with unequal bond dipoles."],["A dative (coordinate) covalent bond has:",["both electrons from one atom","electrons from two atoms","no electrons","metallic electrons"],0,"One atom donates the shared pair."],["The noble gases are stable because they have:",["full outer shells","one electron","no protons","unpaired electrons"],0,"Full octets make them unreactive."],["Sodium chloride conducts electricity when:",["solid","molten or dissolved","covalently bonded","in gas state only"],1,"Ions are free to move when molten or dissolved."],["Diamond has a high melting point because it is:",["ionic","metallic","a giant covalent network","molecular"],2,"Strong covalent bonds link all carbon atoms."],["Van der Waals forces are:",["strong ionic forces","weak intermolecular forces","metallic bonds","covalent bonds"],1,"They are weak attractions between molecules."],["Which gas is the third most abundant in dry air?",["Carbon dioxide is the most abundant gas in dry air","Hydrogen is the most abundant gas in dry air","Helium is the most abundant gas in dry air","Argon is the third most abundant gas in dry air, after nitrogen and oxygen"],3,"Dry air is about 78% nitrogen, 21% oxygen, then about 0.9% argon."]]},{"name":"Set 6: Mole Concept and Stoichiometry","qs":[["The relative formula mass of CaCO3 (Ca=40, C=12, O=16) is:",["52","60","100","72"],2,"40 + 12 + 48 = 100."],["Number of moles in 36 g of water (M = 18) is:",["0.5","1","2","18"],2,"moles = mass / molar mass = 36/18 = 2."],["Mass of 0.5 mol of NaOH (M = 40) is:",["10 g","20 g","40 g","80 g"],1,"0.5 × 40 = 20 g."],["The number of molecules in 2 moles of CO2 is:",["6.02 ×10²³","1.204 ×10²⁴","3.01 ×10²³","12.04 ×10²³"],1,"2 × 6.02 ×10²³ = 1.204 ×10²⁴."],["In the reaction 2H2 + O2 gives 2H2O, the mole ratio of H2 to O2 is:",["1:1","2:1","1:2","3:1"],1,"Coefficients give 2 mol H2 to 1 mol O2."],["Empirical formula is the:",["actual number of atoms","simplest whole number ratio of atoms","formula of an ion","formula of a gas only"],1,"It gives the lowest ratio of atoms."],["Percentage of carbon in CO2 (C=12, O=16) is:",["12%","27.3%","44%","50%"],1,"12/44 × 100 = 27.3 percent."],["Volume of 0.5 mol of O2 at STP is:",["11.2 dm3","22.4 dm3","5.6 dm3","44.8 dm3"],0,"0.5 × 22.4 = 11.2 dm3."],["Concentration of a solution with 4 g NaOH (M = 40) in 500 cm3 is:",["0.1 mol/dm3","0.2 mol/dm3","0.4 mol/dm3","2 mol/dm3"],1,"4/40 = 0.1 mol; 0.1 / 0.5 dm3 = 0.2 mol/dm3."],["The limiting reagent is the reactant that:",["is in excess","is used up first","is a catalyst","does not react"],1,"It determines the maximum amount of product."],["Percentage yield is calculated as:",["theoretical / actual x 100","actual / theoretical x 100","mass / volume","moles x molar mass"],1,"Percentage yield = actual / theoretical x 100."],["Molar mass of H2SO4 (H=1, S=32, O=16) is:",["34","64","98","96"],2,"2 + 32 + 64 = 98."],["Number of atoms in 1 mole of ozone (O3) molecules is:",["6.02 ×10²³","1.806 ×10²⁴","3.01 ×10²³","2.0 ×10²³"],1,"Each molecule has 3 atoms; 3 × 6.02 ×10²³ = 1.806 ×10²⁴."],["A solution of 1 mol/dm3 contains how many moles in 250 cm3?",["0.25","0.5","1","4"],0,"1 × 0.25 dm3 = 0.25 mol."],["Mass of 2 moles of Al (A=27) is:",["13.5 g","27 g","54 g","108 g"],2,"2 × 27 = 54 g."]]},{"name":"Set 7: Gas Laws and Air","qs":[["Boyle's law states that at constant temperature, pressure and volume are:",["directly proportional","inversely proportional","equal","unrelated"],1,"P x V is constant at constant temperature."],["Charles's law relates volume and:",["pressure","temperature in kelvin","mass","density"],1,"At constant pressure V is proportional to absolute temperature."],["The percentage of nitrogen in dry air by volume is about:",["21%","78%","0.03%","1%"],1,"Nitrogen forms about 78 percent of air."],["Oxygen in air is about:",["78%","21%","0.9%","0.03%"],1,"Oxygen is roughly one fifth of air."],["The gas that makes up about 0.03% of air is:",["argon","carbon dioxide","neon","helium"],1,"Carbon dioxide is a trace component of air."],["Standard temperature in kelvin is:",["0 K","273 K","298 K","373 K"],1,"STP uses 273 K and 1 atm."],["Which gas is the most abundant noble gas in air?",["helium","neon","argon","krypton"],2,"Argon is about 0.93 percent of air."],["The gas used for the test of hydrogen is:",["oxygen","a lighted splint giving a pop sound","carbon dioxide turns blue","chlorine turns litmus red"],1,"Hydrogen burns with a squeaky pop."],["Carbon dioxide turns limewater:",["blue","colourless","milky","red"],2,"Calcium carbonate precipitate forms, making it milky."],["Ammonia gas is:",["acidic","neutral","alkaline","inert"],2,"Ammonia dissolves to form a basic solution."],["Which gas relights a glowing splint?",["hydrogen","carbon dioxide","oxygen","nitrogen"],2,"Oxygen supports combustion."],["Pressure of a gas increases when:",["temperature decreases at fixed volume","volume increases at fixed temperature","temperature increases at fixed volume","mass decreases"],2,"Gay-Lussac's law: pressure rises with temperature at fixed volume."],["The gas with the lowest density is:",["oxygen","hydrogen","carbon dioxide","chlorine"],1,"Hydrogen is the lightest gas."],["Greenhouse gases in air include:",["nitrogen and argon","carbon dioxide and methane","neon and helium","oxygen only"],1,"CO2 and methane trap heat."],["Molar volume at room temperature and pressure (25 C, 1 atm) is about:",["22.4 dm3","24 dm3","11.2 dm3","24 cm3"],1,"At RTP it is about 24 dm3 per mole."]]},{"name":"Set 8: Water and Solutions","qs":[["Hard water is caused mainly by dissolved:",["sodium chloride only","calcium and magnesium salts","oxygen","nitrogen"],1,"Ca and Mg ions cause hardness."],["Temporary hardness can be removed by:",["filtration","boiling","decantation","sublimation"],1,"Boiling precipitates the carbonates."],["Permanent hardness is removed by:",["boiling only","adding washing soda","evaporating air","cooling"],1,"Washing soda precipitates the hardness ions."],["A solvent that dissolves most substances is called:",["universal solvent","inert gas","catalyst","ion exchanger"],0,"Water is called the universal solvent."],["The pH of a neutral solution at 25 C is:",["0","7","9","14"],1,"Neutral solutions have pH 7."],["Litmus paper turns red in:",["alkali","acid","water","salt"],1,"Acids turn blue litmus red."],["Solubility is the maximum mass of solute that:",["evaporates","dissolves in 100 g solvent at a given temperature","reacts","is a gas"],1,"It is measured as grams per 100 g of solvent."],["Saturated solution contains:",["no solute","maximum solute at a temperature","no solvent","only gases"],1,"No more solute dissolves."],["Water is made of hydrogen and oxygen in the ratio by mass:",["1:1","2:1","1:8","8:1"],2,"Two H (2 g) to O (16 g) gives 1:8."],["Water purification by chlorine kills:",["only oxygen","microbes","salts","metal ions"],1,"Chlorine kills harmful bacteria."],["Which is a water pollutant?",["oxygen","sodium chloride in small amount","detergents","nitrogen gas"],2,"Detergents and industrial waste pollute water."],["The formula of hydrated copper(II) sulphate is:",["CuSO4","CuSO4.5H2O","CuS","Cu2SO4"],1,"Blue crystals contain five water molecules."],["Electrolysis of water produces:",["hydrogen and oxygen","hydrogen only","oxygen only","carbon dioxide"],0,"Water splits into H2 at cathode and O2 at anode."],["The volume ratio of hydrogen to oxygen in electrolysis of water is:",["1:1","2:1","1:2","3:1"],1,"Two volumes of H2 for one of O2."],["An aqueous solution that conducts electricity is an:",["electrolyte","non-electrolyte","gas","metal"],0,"Ions in solution carry current."]]},{"name":"Set 9: Acids, Bases and Salts","qs":[["An acid is a substance that:",["accepts protons","donates protons (H+)","contains OH- ions","is neutral"],1,"Brønsted acids donate H+."],["A base is a substance that:",["donates protons","accepts protons","donates electrons","contains H+"],1,"Bases accept H+ ions."],["The product of neutralisation of an acid and base is:",["salt and water","oxygen","hydrogen","carbon dioxide only"],0,"Acid + base gives salt and water."],["Which is a strong acid?",["ethanoic acid","carbonic acid","hydrochloric acid","citric acid"],2,"HCl ionises completely in water."],["Sodium hydroxide is an example of:",["weak acid","strong base","salt","neutral oxide"],1,"NaOH is a strong alkali."],["A salt formed from a strong acid and a weak base is:",["neutral","acidic","alkaline","inert"],1,"Hydrolysis produces H+ ions."],["The gas evolved when dilute acid reacts with a metal carbonate is:",["hydrogen","oxygen","carbon dioxide","chlorine"],2,"CO2 is released with effervescence."],["Titration is used to determine:",["melting point","concentration of a solution","density of gas","colour of solid"],1,"Titration finds unknown concentration."],["An indicator used to show end point in acid-base titration of HCl and NaOH is:",["phenolphthalein","starch","biuret","Benedict"],0,"It changes colour in the alkaline pH range."],["Lime water is:",["an acid","a base","a salt","an element"],1,"Calcium hydroxide solution is alkaline."],["Rust is chemically:",["iron(III) oxide hydrate","iron sulphide","iron chloride","copper oxide"],0,"Hydrated iron oxide forms when iron rusts."],["Oxides that react with both acids and bases are:",["basic oxides","acidic oxides","amphoteric oxides","neutral oxides"],2,"Aluminium oxide is amphoteric."],["The pH of a 0.01 M HCl solution is approximately:",["1","2","7","12"],1,"[H+] = 10⁻² gives pH 2."],["Common salt is chemically:",["NaOH","NaCl","Na2CO3","NaNO3"],1,"Sodium chloride is table salt."],["Which reagent identifies sulphate ion?",["dilute HCl then barium chloride","silver nitrate only","limewater","litmus"],0,"Barium chloride gives white precipitate of BaSO4."]]},{"name":"Set 10: Rates of Reaction and Energy","qs":[["A catalyst increases the rate of a reaction by:",["increasing temperature","lowering activation energy","increasing mass","changing products"],1,"It provides an alternative pathway with lower activation energy."],["Exothermic reactions:",["absorb heat","release heat to surroundings","have no energy change","need light only"],1,"Heat is given out, temperature of surroundings rises."],["Endothermic reactions have a:",["positive enthalpy change","negative enthalpy change","zero enthalpy","no energy"],0,"Energy is absorbed, so delta H is positive."],["Increasing concentration of reactants generally:",["decreases rate","increases rate","stops reaction","has no effect"],1,"More collisions per unit time."],["Powdered solids react faster than lumps because:",["surface area is larger","mass is bigger","temperature rises","pressure drops"],0,"More particles are exposed."],["The unit of rate of reaction is commonly:",["mol per dm3 per second","grams","kelvin","cm"],0,"Concentration change per time."],["Photosynthesis is an example of:",["exothermic reaction","endothermic reaction","neutralisation","precipitation"],1,"Plants absorb light energy."],["Burning of fuel is:",["endothermic","exothermic","isothermal","catalytic"],1,"Heat and light are released."],["Which factor does NOT affect rate of reaction?",["temperature","catalyst","colour of reactant","surface area"],2,"Colour is not a kinetic factor."],["A reversible reaction reaches equilibrium when:",["reactions stop","forward and backward rates are equal","products are zero","temperature is zero"],1,"Dynamic equilibrium has equal rates."],["Le Chatelier's principle predicts that increasing temperature favours:",["the endothermic direction","the exothermic direction always","no change","a catalyst effect"],0,"Heat is absorbed to offset the increase."],["Activation energy is:",["energy released","minimum energy for reaction to occur","energy of products","heat of combustion"],1,"Colliding particles must have this energy."],["Enzymes are biological:",["solvents","catalysts","indicators","salts"],1,"They speed up reactions in living things."],["The reaction between zinc and dilute acid is best monitored by measuring:",["colour change","volume of gas evolved","pH only","melting point"],1,"Hydrogen gas evolved shows reaction progress."],["Bond breaking is:",["exothermic","endothermic","isothermic","catalytic"],1,"Energy must be supplied to break bonds."]]},{"name":"Set 11: Electrochemistry and Redox","qs":[["Oxidation is:",["gain of electrons","loss of electrons","gain of protons only","loss of neutrons"],1,"OIL RIG: oxidation is loss of electrons."],["Reduction is:",["loss of electrons","gain of electrons","loss of oxygen","gain of hydrogen only"],1,"Gaining electrons reduces the oxidation state."],["The electrode where oxidation occurs in an electrolytic cell is:",["cathode","anode","salt bridge","electrolyte"],1,"Anode is positive and oxidation occurs there."],["During electrolysis, cations move toward the:",["anode","cathode","salt bridge","electrolyte surface"],1,"Positive ions are attracted to the negative cathode."],["Faraday's first law states that mass deposited is proportional to:",["time only","quantity of electricity passed","voltage only","temperature"],1,"Mass depends on charge passed."],["One Faraday of charge is approximately:",["96500 C","6.02 ×10²³ C","1 C","9650 C"],0,"1 F = 96500 coulombs."],["Electrolysis of concentrated brine produces chlorine at the:",["cathode","anode","both electrodes","salt bridge"],1,"Chloride ions are oxidised at the anode."],["Which metal is most reactive?",["copper","gold","potassium","silver"],2,"Potassium is at the top of the reactivity series."],["A simple cell converts:",["electrical energy to chemical","chemical energy to electrical","heat to light","light to sound"],1,"Chemical reactions drive electric current."],["Corrosion of iron is prevented by:",["painting","keeping it wet","exposing to acid","heating only"],0,"Paint blocks oxygen and water."],["Galvanising protects iron by coating it with:",["tin","zinc","copper","lead"],1,"Zinc corrodes first as sacrificial protection."],["Electrolyte is a substance that:",["conducts by free ions when molten or dissolved","is a metal","is a gas","is an insulator always"],0,"Ions carry current."],["The Daniell cell uses zinc and:",["copper","iron","lead","silver"],0,"Copper and zinc half cells form a classic cell."],["Which electrode is the negative terminal in a galvanic cell?",["cathode","anode","inert electrode","salt bridge"],1,"Anode is the site of oxidation and negative in galvanic cells."],["Electroplating a spoon with silver: the spoon is connected as the:",["anode","cathode","electrolyte only","catalyst"],1,"Silver ions are reduced onto the spoon at the cathode."]]},{"name":"Set 12: Periodic Table and Trends","qs":[["Element with atomic number 11 is:",["sodium","magnesium","neon","lithium"],0,"Atomic number 11 is sodium, Na."],["The noble gases are found in which group of the periodic table?",["Group 1","Group 7","Group 0 (Group 18)","Group 2"],2,"Noble gases have full outer shells and sit in Group 0 (Group 18)."],["Across a period from left to right, atomic radius:",["increases","decreases","stays constant","doubles"],1,"Nuclear charge rises and pulls the electrons closer."],["The most electronegative element is:",["oxygen","chlorine","fluorine","nitrogen"],2,"Fluorine has the highest electronegativity (4.0)."],["Metallic character of elements down a group:",["decreases","increases","stays the same","becomes zero"],1,"Atoms get bigger and lose outer electrons more easily."],["The period number of an element tells you its:",["number of valence electrons","number of electron shells","atomic mass","number of neutrons"],1,"Period number equals the number of occupied electron shells."],["Which element is a metalloid?",["sulphur","silicon","sodium","chlorine"],1,"Silicon has properties between metals and non-metals."],["Electronic configuration 2,8,8,2 belongs to:",["calcium","magnesium","argon","potassium"],0,"Calcium has 20 electrons: 2,8,8,2."],["The halogens belong to which group?",["Group 1","Group 2","Group 7 (VII)","Group 0"],2,"Halogens have seven electrons in the outer shell."],["Alkali metals belong to:",["Group 1","Group 2","Group 7","Group 3"],0,"Alkali metals have one valence electron."],["Which element has the highest first ionisation energy?",["helium","neon","argon","krypton"],0,"Helium has the smallest atom, so its outer electron is held most tightly."],["Transition elements are found in the:",["s-block only","d-block","f-block only","Group 0"],1,"Transition elements occupy the d-block of the periodic table."],["Which element has the lowest first ionisation energy?",["lithium","sodium","potassium","caesium"],3,"Caesium is the largest alkali metal, so it loses its outer electron most easily."],["Which is the largest atom in period 3 (noble gas excluded)?",["sodium","argon","chlorine","magnesium"],0,"Sodium has the lowest nuclear charge in period 3, so its radius is largest."],["The valency of a Group 2 element is:",["1","2","3","4"],1,"Group 2 elements lose two electrons to form 2+ ions."]]},{"name":"Set 13: Alkanes and Alkenes","qs":[["The general formula of alkanes is:",["CnH2n","CnH2n+2","CnH2n-2","CnH4"],1,"Alkanes are saturated: CnH2n+2."],["The general formula of alkenes is:",["CnH2n+2","CnH2n","CnH2n-2","CnH2"],1,"Alkenes have one C=C double bond, giving CnH2n."],["Complete combustion of methane gives:",["CO and H2O","CO2 and H2O","C and H2O","CO2 and H2"],1,"CH4 + 2O2 gives CO2 + 2H2O."],["Bromine water is used to test for:",["unsaturation (C=C)","acids","alkalis","reducing sugars"],0,"Alkenes decolourise bromine water."],["Addition of hydrogen to ethene gives:",["ethane","ethyne","propane","methane"],0,"C2H4 + H2 gives C2H6 (ethane)."],["The name of C3H8 is:",["ethane","propane","butane","pentane"],1,"Three carbons: propane."],["Cracking of alkanes produces:",["alkenes and smaller alkanes","only water","only carbon","alkynes only"],0,"Long chains are broken into shorter, more useful molecules."],["Butane has an isomer called:",["methylpropane","propene","ethyne","pentane"],0,"Methylpropane has the same formula C4H10 but a branched chain."],["Methane reacts with chlorine in the presence of:",["ultraviolet light","low temperature","water","nickel catalyst only"],0,"UV light starts the free radical substitution."],["Members of a homologous series differ from each other by:",["a CH2 unit","the same molecular formula","the same boiling point","the same number of carbons"],0,"Each member adds one CH2 group."],["Octane contains how many carbon atoms?",["6","7","8","9"],2,"Octane (C8H18) has eight carbons."],["Ethyne belongs to which homologous series?",["alkanes","alkenes","alkynes","alcohols"],2,"Ethyne has a C triple bond, so it is an alkyne."],["Ethyne reacts with excess hydrogen to give:",["ethane","ethene","methane","propane"],0,"Two hydrogen additions saturate the triple bond."],["Polymer made from ethene is:",["polythene","polypropene","PVC","nylon"],0,"Many ethene units join to form polythene."],["The gaseous alkene is:",["ethene","octene","hexene","decene"],0,"Ethene is the simplest alkene and is a gas at room temperature."]]},{"name":"Set 14: Alcohols, Acids and Esters","qs":[["The functional group of alcohols is:",["-COOH","-OH","-CHO","-CO-"],1,"Alcohols contain the hydroxyl group, -OH."],["The functional group of a carboxylic acid is:",["-OH","-COOH","-CHO","-COO-"],1,"Carboxylic acids contain -COOH."],["Ethanol is oxidised by acidified potassium dichromate first to:",["ethanal","ethane","ethene","methanol"],0,"Mild oxidation gives ethanal, then ethanoic acid."],["Ethanol and ethanoic acid react to form:",["ethyl ethanoate","methyl methanoate","ethyl propanoate","propyl ethanoate"],0,"Esterification gives ethyl ethanoate and water."],["The catalyst used in esterification is:",["concentrated H2SO4","NaOH","nickel","platinum only"],0,"Concentrated sulphuric acid speeds up ester formation and removes water."],["Fermentation of glucose by yeast gives:",["ethanol and carbon dioxide","ethene and water","methane and oxygen","ethanoic acid only"],0,"C6H12O6 gives 2C2H5OH and 2CO2."],["The sour taste of vinegar is due to:",["ethanoic acid","ethanol","ethanal","propanone"],0,"Vinegar is dilute ethanoic acid."],["The alcohol with three carbon atoms is:",["methanol","ethanol","propanol","butanol"],2,"Propanol has three carbons."],["Alcohols can be identified using:",["sodium metal, giving hydrogen gas","litmus paper","lime water","Benedict solution"],0,"Alcohols react with sodium to release hydrogen."],["Soap is made by a reaction called:",["saponification","esterification","hydrogenation","cracking"],0,"Alkali hydrolysis of fats is saponification."],["Esterification is best described as a:",["reversible reaction","complete reaction only","precipitation","redox reaction only"],0,"Water is formed, so the reaction can go either way."],["Esters are known for their:",["fruity smell","rotten egg smell","pungent acid smell","lack of smell"],0,"Esters give fruit flavours and fragrances."],["Dehydration of ethanol with concentrated H2SO4 at 170 C gives:",["ethene","ethyne","ethanal","ethane"],0,"Water is removed from ethanol to give ethene."],["Ethanol is commonly used as:",["an antiseptic","a bleaching agent","a fertiliser","a drying agent"],0,"Ethanol kills microbes and is used as a disinfectant."],["Which compound gives effervescence with sodium carbonate?",["ethanoic acid","ethanol","ethane","ethene"],0,"Acids react with carbonates to release carbon dioxide."]]},{"name":"Set 15: Polymers and Macromolecules","qs":[["The monomer of PVC is:",["chloroethene","ethene","propene","ethanol"],0,"PVC is poly(chloroethene)."],["Addition polymerisation needs monomers that are:",["unsaturated","saturated","alcohols","acids"],0,"A C=C double bond opens up to join monomers."],["Nylon is an example of a:",["condensation polymer","addition polymer","natural polymer","metal"],0,"Nylon forms with loss of small molecules such as water."],["Which of these is a natural polymer?",["starch","polythene","PVC","nylon"],0,"Starch is made by plants from glucose units."],["Proteins are polymers of:",["amino acids","glucose","fatty acids","glycerol"],0,"Amino acids join by peptide links."],["Natural rubber is a polymer of:",["isoprene","ethene","propene","butane"],0,"Rubber is polyisoprene."],["Plastic waste is a problem because it is:",["non-biodegradable","biodegradable","soluble in water","alkaline"],0,"Plastics do not break down quickly in the environment."],["The monomer of cellulose is:",["glucose","fructose","sucrose","galactose"],0,"Cellulose is a chain of glucose units."],["Polythene is made from:",["ethene","ethyne","methane","propane"],0,"Many ethene molecules join by addition."],["Polyesters are formed by:",["condensation","addition","substitution","hydrolysis only"],0,"Small molecules such as water are lost as the chains link."],["Starch on hydrolysis finally gives:",["glucose","fructose","sucrose","galactose"],0,"Starch breaks down into glucose units."],["The monomer of polypropene is:",["propene","ethene","propane","butene"],0,"Polypropene is made from propene."],["A thermoplastic is a plastic that:",["softens on heating","hardens on heating permanently","dissolves in water","reacts with acid"],0,"Thermoplastics can be melted and reshaped repeatedly."],["Which is a thermosetting plastic?",["Bakelite","polythene","PVC","polystyrene"],0,"Thermosetting plastics set permanently when heated."],["The degree of polymerisation means:",["the number of monomer units in a chain","the number of carbons in a monomer","the melting point","the molar mass of the solvent"],0,"It counts how many repeating units make up one polymer molecule."]]},{"name":"Set 16: Chemical Equilibrium and Le Chatelier","qs":[["For the reaction N2 + 3H2 <=> 2NH3 (exothermic), raising the temperature shifts equilibrium to the:",["right","left","no shift","stops"],1,"Heat favours the endothermic direction, which is the reverse reaction."],["Increasing pressure on N2 + 3H2 <=> 2NH3 shifts equilibrium to the side with:",["more gas molecules","fewer gas molecules","more water","no gas"],1,"Pressure favours the side with fewer gas molecules: 2NH3."],["A catalyst in an equilibrium reaction:",["changes the equilibrium position","speeds up both forward and reverse reactions equally","stops the reaction","makes the reaction endothermic"],1,"A catalyst only helps the system reach equilibrium faster."],["Equilibrium in a closed system is reached when:",["forward and reverse rates are equal","the reaction stops","all reactants disappear","the temperature falls to zero"],0,"Concentrations stay constant because both rates match."],["Le Chatelier's principle states that a system at equilibrium will:",["oppose any change applied to it","always move right","never change","always move left"],0,"The system adjusts to partly counteract the change."],["Adding more reactant to an equilibrium mixture shifts the equilibrium to the:",["right","left","stops","no change in direction"],0,"Extra reactant is used up, so products increase."],["The Haber process is used to make:",["ammonia","sulphuric acid","nitric acid","sodium hydroxide"],0,"N2 and H2 are combined to make NH3 under high pressure."],["Which condition is used in the Contact process to increase SO2 conversion?",["high pressure","low temperature only","vanadium(V) oxide catalyst","no catalyst"],2,"Vanadium(V) oxide speeds up the reaction without being used up."],["In the Haber process, the iron catalyst is used to:",["speed up attainment of equilibrium","make the yield 100%","lower the pressure","absorb ammonia"],0,"Catalysts do not change the equilibrium yield, only the speed."],["A reversible reaction is shown by:",["the sign","the double arrow","a single arrow","a question mark"],1,"Double arrows show both directions occur."],["The equilibrium constant for an exothermic reaction decreases when:",["temperature rises","temperature falls","a catalyst is added","pressure is removed only"],0,"Rising temperature shifts the equilibrium toward reactants."],["Dissolving ammonium chloride in water is:",["endothermic","exothermic","neutral","non-reversible"],0,"The solution gets colder, so energy is absorbed."],["Which change shifts 2SO2 + O2 <=> 2SO3 (exothermic) to the right, giving more SO3?",["raising the temperature","adding more SO3 to the mixture","removing SO3 as it forms","adding a noble gas at constant volume"],2,"Removing a product pulls the equilibrium to the right, so more SO3 forms. Raising temperature favours the left (endothermic) direction, and adding product shifts it left."],["Hydrogen and iodine react to form HI. Increasing volume (lowering pressure) causes:",["no change in position","shift toward more HI","shift toward H2 and I2","complete reaction"],0,"Equal moles of gas on each side means pressure does not shift equilibrium."],["An equilibrium position is described as favouring products when:",["K is large","K is small","K is zero","K is negative"],0,"A large equilibrium constant means many products form."]]},{"name":"Set 17: Energetics and Enthalpy Change","qs":[["A reaction that gives out heat to the surroundings is:",["exothermic","endothermic","isothermic","neutral"],0,"Exothermic reactions release energy, so the temperature rises."],["The enthalpy change of an exothermic reaction is:",["positive","negative","zero","infinite"],1,"Energy is released, so delta H is negative."],["Melting ice absorbs heat, so the process is:",["endothermic","exothermic","neutral","reversible only"],0,"Energy is taken in from the surroundings."],["Bond breaking is always:",["endothermic","exothermic","zero energy","reversible"],0,"Energy must be supplied to break bonds."],["Bond making is always:",["exothermic","endothermic","zero energy","impossible"],0,"Energy is released when new bonds form."],["The standard unit of enthalpy change is:",["kJ/mol","mol/kJ","kg","K"],0,"Enthalpy change is quoted in kilojoules per mole."],["Burning fuel is an example of a/an:",["exothermic reaction","endothermic reaction","decomposition","precipitation"],0,"Combustion releases heat energy."],["The reaction between sodium and water is:",["exothermic","endothermic","isothermic","non-spontaneous"],0,"The reaction gives out heat and hydrogen."],["Photosynthesis is an example of an:",["endothermic reaction","exothermic reaction","neutralisation","combustion"],0,"Plants absorb light energy to build glucose."],["Hess's law states that the total enthalpy change depends only on:",["initial and final states","the route taken","the catalyst used","the volume"],0,"Enthalpy is a state function."],["The heat of combustion of a fuel is measured in:",["kJ/mol","mol/L","g/cm3","atm"],0,"Combustion heat is enthalpy per mole of fuel burnt."],["In an endothermic reaction, the products have:",["more energy than reactants","less energy than reactants","equal energy","no energy"],0,"Energy is absorbed, so products sit higher on the energy profile."],["The heat of neutralisation is usually about:",["-57 kJ/mol","+57 kJ/mol","-500 kJ/mol","0 kJ/mol"],0,"Strong acid and strong base neutralisation releases about 57 kJ per mole of water."],["Which of these is an endothermic process?",["neutralisation","respiration","thermal decomposition of CaCO3","combustion of alcohol"],2,"Heating calcium carbonate needs continuous heat input."],["A bond energy is the energy needed to:",["break one mole of a bond","form one mole of a bond only","melt the substance","heat the solution"],0,"Bond energy is measured for breaking bonds."]]},{"name":"Set 18: Rates of Reaction","qs":[["Which factor does NOT increase the rate of a reaction?",["higher temperature","larger surface area","higher concentration","lower pressure for a gas reaction"],3,"Lower pressure reduces collisions between gas particles."],["A catalyst increases reaction rate by:",["lowering the activation energy","increasing the activation energy","using up reactants","changing the products"],0,"It provides an alternative pathway with lower activation energy."],["Powdered marble reacts faster with acid than a lump of marble because:",["it has a larger surface area","it is more concentrated","it is more reactive chemically","it is hotter"],0,"More surface is exposed for collisions."],["Measuring the volume of gas collected per minute is used to find:",["rate of reaction","atomic mass","equilibrium constant","pH"],0,"Faster gas production means a faster rate."],["The rate of a reaction is the change in amount of product per:",["unit time","unit mass","unit volume only","mole only"],0,"Rate = change in quantity divided by time."],["Increasing temperature speeds up reactions mainly by:",["increasing the number of successful collisions","reducing activation energy","increasing mass","decreasing volume"],0,"More particles have energy above activation energy."],["Which gas is produced when zinc reacts with dilute hydrochloric acid?",["hydrogen","oxygen","chlorine","carbon dioxide"],0,"Zn + 2HCl gives ZnCl2 and H2."],["In the decomposition of hydrogen peroxide, the catalyst used is:",["manganese(IV) oxide","iron","copper sulphate","sodium chloride"],0,"MnO2 speeds up the breakdown of H2O2 into oxygen."],["The effect of concentration on rate is explained by:",["more particles per unit volume giving more collisions","particles becoming heavier","particles becoming bigger","colour change"],0,"Higher concentration means more frequent collisions."],["The activation energy is:",["the minimum energy needed for a reaction to occur","the energy released in combustion","the energy of a catalyst","the energy of the products"],0,"Colliding particles need at least this energy to react."],["A reaction that is fastest at the start and slows down over time is typical of:",["reaction rate decreasing as reactants are used up","constant rate always","zero rate","increasing rate always"],0,"Concentration of reactant falls, so collisions become less frequent."],["The effect of light on the rate of photochemical reactions is shown by:",["silver chloride decomposing in sunlight","water boiling","rust forming slowly","ice melting"],0,"Light provides energy to break bonds in silver chloride."],["If temperature rises by 10 C, the rate of many reactions roughly:",["doubles","halves","stays the same","becomes zero"],0,"A rough rule: rate doubles for each 10 degrees rise."],["Adding a catalyst to a reaction at equilibrium:",["speeds up the time to reach equilibrium","changes the final yield","stops the reaction","makes it endothermic"],0,"The equilibrium position is not changed by catalysts."],["The oxidation number of nitrogen in NH3 is:",["-3","+3","+5","0"],0,"N + 3(+1) = 0 gives N = -3."]]},{"name":"Set 19: Redox Reactions and Oxidation Numbers","qs":[["Oxidation is the:",["gain of electrons","loss of electrons","gain of oxygen only","loss of hydrogen only"],1,"OIL RIG: oxidation is loss of electrons."],["Reduction is the:",["loss of electrons","gain of electrons","loss of oxygen only","gain of protons"],1,"Reduction is gain of electrons (RIG)."],["The oxidation number of hydrogen in H2O is:",["+1","-1","0","+2"],0,"Hydrogen is +1 when bonded to non-metals."],["The oxidation number of oxygen in most compounds is:",["-2","+2","-1","0"],0,"Oxygen usually has an oxidation state of -2."],["In MnO4- the oxidation state of manganese is:",["+7","+4","+2","+5"],0,"Total charge -1 = Mn + 4(-2), so Mn = +7."],["Which substance is a reducing agent in Fe2+ + Ag+ gives Fe3+ + Ag?",["Fe2+","Ag+","Fe3+","Ag"],0,"Fe2+ loses electrons, so it is oxidised and acts as a reducing agent."],["Displacement of copper from copper sulphate by zinc is a:",["redox reaction","neutralisation","precipitation only","hydrolysis"],0,"Zinc is oxidised and copper ions are reduced."],["The oxidation number of sulphur in SO2 is:",["+4","+6","-2","0"],0,"S + 2(-2) = 0 gives S = +4."],["Oxidising agents:",["gain electrons and are reduced","lose electrons and are oxidised","do nothing in reactions","are always metals"],0,"Oxidising agents are reduced in the reaction."],["The oxidation number of an element in its free state is:",["0","+1","-1","+2"],0,"Free elements have zero oxidation number."],["Which is an oxidising agent?",["acidified potassium manganate(VII)","zinc","hydrogen","carbon monoxide"],0,"Potassium manganate(VII) gains electrons and is reduced."],["In the reaction Cl2 + 2Br- gives 2Cl- + Br2, the chlorine is:",["reduced","oxidised","neutral","a catalyst"],0,"Cl goes from 0 to -1, which is gain of electrons."],["The oxidation state of carbon in CO2 is:",["+4","+2","0","-4"],0,"C + 2(-2) = 0 gives C = +4."],["Which of these is a reducing agent?",["sulphur dioxide","hydrogen sulphide","hydrogen peroxide only","potassium manganate(VII)"],1,"H2S can donate electrons, so it is a reducing agent."],["A half-equation shows:",["the oxidation or reduction part of a reaction","only the product","only the catalyst","the temperature"],0,"It shows electron transfer for one half of a redox reaction."]]},{"name":"Set 20: Electrolysis","qs":[["Electrolysis is the process of:",["decomposing a compound using electricity","making electricity from chemicals","melting ice","distilling water"],0,"Electric current breaks down an electrolyte."],["An electrolyte is a substance that:",["conducts electricity when molten or dissolved","is always a metal","is a gas at room temperature","is insoluble in water"],0,"Ions carry the charge when the compound is molten or in solution."],["At the cathode, positive ions are:",["reduced","oxidised","neutral","destroyed"],0,"Cations gain electrons at the cathode."],["At the anode, negative ions are:",["oxidised","reduced","neutral only","catalysts"],0,"Anions lose electrons at the anode."],["During electrolysis of molten lead(II) bromide, lead forms at:",["the cathode","the anode","both electrodes","the solution"],0,"Pb2+ ions gain electrons at the cathode."],["Electrolysis of concentrated brine (NaCl solution) produces chlorine at the:",["anode","cathode","both electrodes","neither"],0,"Chloride ions lose electrons at the anode."],["The product at the cathode during electrolysis of concentrated brine is:",["hydrogen","chlorine","sodium","oxygen"],0,"Hydrogen is less reactive than sodium, so water is reduced."],["Electroplating is used to:",["coat an object with a metal","purify water","make salt","produce acid"],0,"A thin layer of metal is deposited on an article."],["In electroplating, the article to be plated is made the:",["cathode","anode","electrolyte","catalyst"],0,"Metal ions are reduced onto the object at the cathode."],["Copper refining uses electrolysis with:",["impure copper as anode","pure copper as anode","pure copper as cathode only","no electrodes"],0,"Impure copper dissolves at the anode and pure copper deposits at the cathode."],["Faraday's first law states that the mass of substance deposited depends on:",["quantity of electricity passed","the colour of the solution","the temperature only","the volume of the cell"],0,"More charge means more substance is deposited."],["Which metal is extracted by electrolysis of its molten oxide?",["aluminium","iron","copper","zinc only"],0,"Aluminium is too reactive for carbon reduction, so electrolysis is used."],["Cryolite is added in aluminium extraction to:",["lower the melting point of alumina","increase the price","form aluminium oxide","absorb oxygen"],0,"It lowers the melting temperature and saves energy."],["Carbon anodes in aluminium extraction are burnt away by:",["oxygen released at the anode","hydrogen released at the cathode","sodium","chlorine only"],0,"Oxygen reacts with the carbon anodes to form CO2."],["Which solution gives oxygen at the anode during electrolysis?",["dilute sulphuric acid","concentrated brine","molten NaCl","copper(II) chloride"],0,"Water is oxidised, releasing oxygen when sulphate ions are not discharged."]]},{"name":"Set 21: Nitrogen, Ammonia and Fertilisers","qs":[["The percentage of nitrogen in dry air is about:",["21%","78%","0.03%","1%"],1,"Air is roughly 78% nitrogen, 21% oxygen."],["Nitrogen is unreactive at room temperature mainly because of its:",["triple bond","single bond","ionic bond","metallic bond"],0,"The N≡N triple bond is very strong."],["Ammonia is prepared in the laboratory by heating an ammonium salt with:",["sodium hydroxide","hydrochloric acid","water only","nitric acid"],0,"NH4Cl + NaOH gives NH3, H2O and NaCl."],["Ammonia gas is tested using:",["damp red litmus paper, which turns blue","limewater","a glowing splint","blue litmus only"],0,"Ammonia is alkaline, so it turns damp red litmus blue."],["The fertiliser ammonium nitrate is made from:",["ammonia and nitric acid","ethanol and nitric acid","sodium and water","calcium carbonate and HCl"],0,"NH3 + HNO3 gives NH4NO3."],["Nitrogen-fixing bacteria found in root nodules of legumes convert nitrogen into:",["ammonia or nitrates","oxygen","carbon dioxide","methane"],0,"They turn atmospheric N2 into compounds plants can use."],["Ammonia dissolves in water to form a solution that is:",["alkaline","acidic","neutral","saturated acid"],0,"NH3 + H2O gives NH4+ and OH-, so it is alkaline."],["Which gas is produced when ammonium chloride reacts with calcium hydroxide?",["ammonia","chlorine","hydrogen","carbon dioxide"],0,"Ammonium salts with alkalis release NH3."],["The Haber process uses nitrogen and hydrogen in a ratio of:",["1:3","3:1","1:1","2:1"],0,"N2 + 3H2 gives 2NH3."],["Oxides of nitrogen released by car engines contribute to:",["acid rain","ozone creation in the stratosphere only","global cooling","hard water"],0,"NO2 dissolves in rain to form nitric acid."],["Nitrogen forms part of which essential biological molecule?",["protein","starch","cellulose","wax"],0,"Proteins contain nitrogen in amino acids."],["Fertilisers containing nitrates are soluble, so they are:",["easily washed away by rain","insoluble in water","non-toxic gases","unreactive"],0,"Soluble nitrates can leach into rivers and cause eutrophication."],["The compound NH4NO3 is an example of a:",["nitrogenous fertiliser","sugar","fat","dye"],0,"It supplies nitrogen to crops."],["Ammonia reacts with hydrogen chloride gas to form:",["white fumes of ammonium chloride","brown fumes of NO2","a green precipitate","hydrogen gas"],0,"White solid ammonium chloride forms as a smoke."],["The industrial catalyst used in the Haber process is:",["iron","nickel","platinum","vanadium(V) oxide"],0,"Iron speeds up ammonia formation."]]},{"name":"Set 22: Sulphur and the Contact Process","qs":[["Sulphur dioxide is a gas with a:",["choking, pungent smell","sweet smell","no smell","smell of almonds"],0,"SO2 is a pungent, toxic gas."],["The Contact process is used to manufacture:",["sulphuric acid","ammonia","nitric acid","hydrochloric acid"],0,"It is the main industrial route to H2SO4."],["In the Contact process, sulphur dioxide is oxidised to sulphur trioxide using:",["vanadium(V) oxide","iron","copper","nickel"],0,"V2O5 is the catalyst."],["Sulphur trioxide is absorbed by:",["concentrated sulphuric acid","water directly","alkaline solution","ethanol"],0,"Direct reaction with water makes a dangerous mist, so H2SO4 is used to absorb SO3."],["Acid rain is caused mainly by:",["sulphur dioxide and nitrogen oxides","carbon monoxide only","oxygen","helium"],0,"These gases form sulphuric and nitric acids in rain."],["Sulphur dioxide turns acidified potassium manganate(VII) from purple to:",["colourless","yellow","green","blue"],0,"SO2 is a reducing agent and decolourises the purple solution."],["Which is the oxidation state of sulphur in H2SO4?",["+6","+4","+2","-2"],0,"2(+1) + S + 4(-2) = 0 gives S = +6."],["Concentrated sulphuric acid acts as a dehydrating agent because it:",["removes water from other compounds","adds water","is alkaline","dissolves metals"],0,"It removes H and O as water from sugar and similar compounds."],["Dilute sulphuric acid reacts with metals to produce:",["a salt and hydrogen","a salt and oxygen","water only","carbon dioxide"],0,"Acid + metal gives salt + H2."],["Sulphur exists in nature as:",["native sulphur and sulphide ores","pure gas only","water-soluble salt only","carbon compound only"],0,"It is found free and in ores such as galena and pyrite."],["The test for sulphate ions uses:",["barium chloride solution producing a white precipitate","silver nitrate producing a yellow precipitate","limewater","litmus paper"],0,"BaSO4 is an insoluble white precipitate."],["A yellow precipitate with silver nitrate indicates the presence of:",["iodide ions","chloride ions","sulphate ions","nitrate ions"],0,"AgI is yellow."],["Sulphur dioxide is removed from flue gases using:",["calcium oxide or calcium carbonate","sodium chloride","water only","ammonia gas only"],0,"The base neutralises the acidic gas."],["Hydrogen sulphide has the smell of:",["rotten eggs","vinegar","almonds","fresh bread"],0,"H2S smells of rotten eggs and is toxic."],["Which gas is evolved when dilute acid reacts with a sulphide?",["hydrogen sulphide","sulphur dioxide","oxygen","chlorine"],0,"Dilute acid reacts with sulphide ions to release H2S."]]},{"name":"Set 23: Metals, Reactivity and Extraction","qs":[["The most reactive metal in the reactivity series listed is:",["potassium","copper","gold","silver"],0,"Potassium is at the top of the reactivity series."],["Metals below carbon in the reactivity series can be extracted by:",["reduction with carbon","electrolysis only","heating alone","distillation"],0,"Carbon reduces their oxides to metals."],["Aluminium is extracted from its ore by:",["electrolysis of molten alumina","reduction with carbon","heating alone","distillation"],0,"Aluminium is too reactive for carbon reduction."],["Iron is extracted in a blast furnace using:",["carbon monoxide to reduce iron(III) oxide","electrolysis","sodium","hydrogen only"],0,"CO reduces Fe2O3 to iron."],["The main ore of iron is:",["haematite","bauxite","galena","cryolite"],0,"Haematite is Fe2O3."],["The main ore of aluminium is:",["bauxite","haematite","galena","chalcopyrite"],0,"Bauxite is hydrated aluminium oxide."],["Galena is an ore of:",["lead","zinc","copper","tin"],0,"Galena is lead(II) sulphide."],["Copper is most commonly obtained from:",["copper pyrites","bauxite","haematite","galena"],0,"Copper pyrites is CuFeS2, the main copper ore."],["Zinc is commonly extracted by:",["roasting zinc blende and reduction with carbon","electrolysis of brine","adding sodium","heating with water"],0,"Zinc sulphide is roasted to oxide and reduced."],["Rust is:",["hydrated iron(III) oxide","pure iron","iron(II) chloride","iron carbonate"],0,"Rust forms when iron reacts with oxygen and water."],["Rusting is prevented by:",["painting, galvanising or oiling","leaving iron in water","adding acid","heating"],0,"Coatings keep oxygen and water away from iron."],["Galvanising means coating iron with:",["zinc","tin only","gold","aluminium oxide"],0,"Zinc protects iron even when scratched."],["An alloy is:",["a mixture of a metal with another element","a pure metal","a non-metal compound","a salt"],0,"Alloys combine metals to improve properties such as hardness."],["Brass is an alloy of:",["copper and zinc","iron and carbon","copper and tin","lead and tin"],0,"Brass is copper plus zinc."],["Steel is an alloy of iron and:",["carbon","sodium","copper","chromium only"],0,"Carbon makes iron harder and stronger."]]},{"name":"Set 24: Qualitative Analysis and Ion Tests","qs":[["Carbon dioxide is identified by its reaction with:",["limewater turning milky","damp litmus turning blue","a glowing splint relighting","bromine water"],0,"CO2 forms insoluble calcium carbonate with lime water."],["Oxygen is detected using a:",["glowing splint relighting","lighted splint going out with a pop","damp red litmus","limewater"],0,"Oxygen relights a glowing splint."],["Hydrogen gas is identified by:",["a burning splint giving a squeaky pop","relighting a glowing splint","turning limewater milky","bleaching litmus"],0,"Hydrogen burns with a squeaky pop."],["Chlorine gas is identified by:",["bleaching damp litmus paper","turning limewater milky","relighting a glowing splint","a pop with a flame"],0,"Chlorine bleaches moist litmus."],["Ammonium ions are detected by warming with NaOH and testing the gas with:",["damp red litmus paper turning blue","limewater","a glowing splint","bromine water"],0,"NH3 turns damp red litmus blue."],["Chloride ions give which precipitate with silver nitrate?",["white","yellow","black","green"],0,"AgCl is a white precipitate."],["Iodide ions give which precipitate with silver nitrate?",["yellow","white","blue","no precipitate"],0,"AgI is yellow."],["Iron(II) ions give what precipitate with sodium hydroxide?",["green","brown","white only","blue"],0,"Fe(OH)2 is green."],["Iron(III) ions give which precipitate with sodium hydroxide?",["reddish-brown","green","white","blue"],0,"Fe(OH)3 is reddish-brown."],["Copper(II) ions give which colour precipitate with sodium hydroxide?",["blue","green","brown","white"],0,"Cu(OH)2 is a pale blue precipitate."],["Calcium ions give which result with sodium hydroxide?",["a white precipitate","a green precipitate","a brown precipitate","no change"],0,"Ca(OH)2 is white, though only partly insoluble."],["Zinc hydroxide dissolves in excess sodium hydroxide, so zinc ions form a:",["white precipitate that dissolves in excess","permanent black precipitate","green solution only","red gas"],0,"Zn(OH)2 is amphoteric."],["The flame test for sodium gives a colour of:",["yellow","red","lilac","green"],0,"Sodium salts give a bright yellow flame."],["The flame test for potassium gives a colour of:",["lilac","yellow","red","blue"],0,"Potassium salts give a lilac flame."],["Which reagent confirms carbonate ions?",["dilute acid producing CO2 that turns limewater milky","silver nitrate only","barium chloride only","red litmus"],0,"Carbonates release CO2 with acid."]]},{"name":"Set 25: Group 1 and Group 2 Elements and Water Hardness","qs":[["Alkali metals react with water to form:",["an alkaline solution and hydrogen","an acid and oxygen","a salt and water only","carbon dioxide"],0,"M + H2O gives MOH + H2."],["The reaction of potassium with water is:",["more vigorous than sodium","less vigorous than lithium","non-existent","identical to calcium"],0,"Reactivity increases down Group 1."],["Group 2 metals are called:",["alkaline earth metals","halogens","noble gases","transition metals"],0,"Group 2 metals form alkaline earth hydroxides."],["Calcium hydroxide solution is known as:",["limewater","brine","Epsom salt","vinegar"],0,"Limewater is calcium hydroxide solution."],["Temporary hardness of water is caused by:",["calcium hydrogencarbonate","calcium sulphate","sodium chloride","magnesium chloride only"],0,"Dissolved hydrogencarbonates are removed by boiling."],["Permanent hardness of water is caused by:",["calcium sulphate and magnesium sulphate","calcium carbonate only","calcium hydroxide","sodium hydroxide"],0,"Sulphates and chlorides cannot be removed by boiling."],["Temporary hardness is removed by:",["boiling","adding soap","adding salt","stirring only"],0,"Boiling decomposes the hydrogencarbonates."],["Hard water causes:",["poor lathering of soap","better lathering","foul smell","high pH"],0,"Calcium ions react with soap to form scum."],["The scum formed in hard water is made of:",["calcium salts of fatty acids","calcium chloride","sodium carbonate","water"],0,"Calcium stearate forms the scum."],["Sodium is stored under:",["paraffin oil","water","air","ethanol"],0,"Sodium reacts with water and oxygen in air."],["Which element is used in the Solvay process for making sodium carbonate?",["sodium chloride","magnesium","lead","copper"],0,"Brine is the raw material."],["The main ore of magnesium is:",["sea water and carnallite","bauxite","haematite","galena"],0,"Magnesium is extracted from sea water and carnallite."],["Magnesium burns in air with a:",["brilliant white flame","yellow flame","blue flame","green flame"],0,"Magnesium gives a bright white light when burning."],["Lime is produced by heating:",["calcium carbonate","calcium chloride","sodium chloride","calcium sulphate"],0,"CaCO3 decomposes to CaO and CO2."],["Which non-metal is a liquid at room temperature?",["bromine","iodine","sulphur","phosphorus"],0,"Bromine is the only non-metal liquid at room temperature among these."]]},{"name":"Set 26: Carbon, Greenhouse Effect and Environment","qs":[["The main greenhouse gas responsible for global warming is:",["carbon dioxide","nitrogen","argon","helium"],0,"CO2 traps heat in the atmosphere."],["Carbon monoxide is dangerous because it:",["binds to haemoglobin more strongly than oxygen","makes blood acidic","destroys the ozone","causes acid rain"],0,"CO reduces oxygen transport in blood."],["Carbon monoxide is produced by:",["incomplete combustion","complete combustion","photosynthesis","neutralisation"],0,"Limited oxygen gives CO instead of CO2."],["The gas that depletes the ozone layer is:",["CFCs","carbon monoxide","sulphur trioxide only","oxygen"],0,"CFCs release chlorine that destroys ozone."],["Carbon dioxide is removed from air by:",["photosynthesis","respiration","combustion","decay only"],0,"Plants use CO2 in photosynthesis."],["Burning fossil fuels increases atmospheric:",["CO2","helium","argon","neon"],0,"Fossil fuels are carbon-based and release CO2."],["Carbonates react with dilute acids to release:",["carbon dioxide","hydrogen","oxygen","chlorine"],0,"Acid + carbonate gives salt, water and CO2."],["Carbon exists in which allotrope that conducts electricity?",["graphite","diamond","fullerene only","charcoal only"],0,"Graphite has delocalised electrons."],["Diamond is hard because it:",["has a giant covalent structure","has ionic bonds","is a metal","has weak forces only"],0,"Each carbon bonds to four others in a rigid network."],["Activated charcoal is used to:",["adsorb impurities and gases","make ammonia","form acid rain","conduct electricity"],0,"It has a large surface area."],["Coal is a:",["fossil fuel rich in carbon","metal ore","salt","mineral oil"],0,"Coal is formed from ancient plant material."],["Eutrophication is caused mainly by:",["excess nitrates and phosphates in water","too much oxygen","salt only","carbon monoxide"],0,"Nutrients cause algae to grow and deplete oxygen."],["The process of breaking down materials by living organisms is:",["biodegradation","electrolysis","fractionation","cracking"],0,"Microorganisms decompose biodegradable waste."],["Water pollution by oil is most harmful to:",["aquatic life","metals","rocks","sand"],0,"Oil blocks oxygen and harms organisms."],["Global warming is mainly caused by:",["greenhouse gases trapping heat","ozone destruction only","sulphur mining","salt water"],0,"Trapped heat warms the planet."]]},{"name":"Set 27: Atomic Structure, Isotopes and Bonding","qs":[["The number of neutrons in carbon-14 is:",["8","6","14","20"],0,"Neutrons = mass number 14 minus proton number 6 = 8."],["Isotopes of the same element differ in:",["number of neutrons","number of protons","atomic number","electron configuration"],0,"Isotopes share protons but differ in neutrons."],["The relative atomic mass of an element is the weighted average of:",["isotope masses","atomic numbers","number of electrons","valencies"],0,"It accounts for each isotope's abundance."],["An ion formed by losing electrons is:",["positive","negative","neutral","unchanged"],0,"Losing electrons leaves a net positive charge."],["The electron configuration of oxygen is:",["2,6","2,8","8,2","2,4"],0,"Oxygen has 8 electrons: 2,6."],["Ionic bonds form between:",["metals and non-metals","two non-metals","two metals","noble gases"],0,"Electrons transfer from metal to non-metal."],["Covalent bonds form by:",["sharing electron pairs","transferring electrons","forming ions","losing protons"],0,"Atoms share pairs of electrons."],["Giant ionic lattices have high melting points because:",["strong electrostatic forces hold ions together","they are covalent","they are gases","they have no charge"],0,"Many strong ionic bonds need much energy to break."],["Simple molecular substances have low melting points because:",["weak intermolecular forces are easily overcome","they have ionic bonds","they are metals","they contain free electrons"],0,"Little energy breaks the forces between molecules."],["Metals conduct electricity because they have:",["delocalised electrons","fixed ions only","covalent bonds","no free charge"],0,"Free electrons carry current."],["Ionic compounds conduct electricity when:",["molten or dissolved","solid","as crystals at room temperature","never"],0,"Ions move freely only when the lattice breaks."],["The number of electrons in a Cl- ion is:",["18","17","16","19"],0,"Chlorine has 17 electrons; the ion gains one."],["A dative (coordinate) covalent bond is formed when:",["both shared electrons come from one atom","no electrons are shared","atoms transfer electrons","ions are formed"],0,"One atom donates the bonding pair."],["Hydrogen bonding is strongest in:",["water","methane","ethane","carbon dioxide"],0,"O-H bonds give strong hydrogen bonding in water."],["Van der Waals forces are weakest between:",["simple non-polar molecules","ions","metal atoms","giant covalent carbon"],0,"Non-polar molecules have only weak temporary dipoles."]]}]};
